/* ─── Buttons: solid (one per view), line (the rest), danger, ghost ─── */
.btn { height: var(--control-md); display: inline-flex; align-items: center; justify-content: center; gap: var(--s3); padding: 0 24px; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; border-radius: var(--radius); transition: transform var(--base), background var(--fast), color var(--fast); }
.btn:active:not(:disabled) { transform: scale(0.98); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn-solid { background: var(--foreground); color: var(--background); }
.btn-solid:hover:not(:disabled) { background: var(--ink-2); }
.btn-line { box-shadow: inset 0 0 0 1px var(--foreground); }
.btn-line:hover:not(:disabled) { background: var(--foreground); color: var(--background); }
.btn-danger { box-shadow: inset 0 0 0 1px var(--danger); color: var(--danger); }
.btn-danger:hover:not(:disabled) { background: var(--danger); color: var(--background); }
.btn-ghost { min-height: 0; padding-inline-start: 0; padding-inline-end: 0; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
.btn-ghost:hover:not(:disabled) { text-decoration-color: currentColor; }
.btn-sm { height: var(--control-sm); padding: 0 12px; font-size: var(--text-xs); }
.btn-lg { height: var(--control-lg); padding: 0 32px; font-size: var(--text-base); }
.btn-ghost.btn-sm, .btn-ghost.btn-lg { height: auto; padding-block: var(--s2); }
.btn-block { width: 100%; }

/* Icon button: a square .btn. */
.btn.btn-icon { height: auto; padding: var(--s3); aspect-ratio: 1; display: inline-grid; place-items: center; line-height: 0; }
.btn.btn-icon.btn-sm { height: auto; padding: var(--s2); }
.btn-icon svg { width: 1em; height: 1em; }

/* Dialog, alert dialog and drawer on Radix. Overlay and content are portalled; they read tokens only. */
.dialog-overlay { position: fixed; inset: 0; z-index: var(--z-drawer); background: color-mix(in srgb, var(--surface) 45%, transparent); animation: dialog-fade var(--base) var(--ease); }
.dialog-content { position: fixed; z-index: var(--z-drawer); top: 50%; left: 50%; transform: translate(-50%, -50%); width: min(520px, 92vw); max-height: 90vh; overflow-y: auto; padding: var(--s6); background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); animation: dialog-pop var(--base) var(--ease); } /* physical: centred with translate, same in both directions */
.dialog-content:focus { outline: none; }
.dialog-header { display: grid; gap: var(--s2); margin-bottom: var(--s5); }
.dialog-footer { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: var(--s3); margin-top: var(--s5); }
.dialog-description { overflow-wrap: anywhere; color: var(--muted); font-size: var(--text-sm); max-width: var(--measure); }
.dialog-close { position: absolute; top: var(--s4); inset-inline-end: var(--s4); padding: var(--s1) var(--s2); font-size: var(--text-sm); text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
@keyframes dialog-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes dialog-pop { from { opacity: 0; transform: translate(-50%, calc(-50% + 8px)); } to { opacity: 1; transform: translate(-50%, -50%); } }
.dialog-title { overflow-wrap: anywhere; font-family: var(--font-display); font-weight: 700; font-size: var(--text-lg); letter-spacing: -0.02em; margin-bottom: var(--s3); } /* sentence case: uppercase is only for .display */

/* Drawer: a Radix Dialog pinned to an edge. Overlay, header and footer reuse dialog.css. */
.drawer-content { position: fixed; z-index: var(--z-drawer); display: flex; flex-direction: column; gap: var(--s4); padding: var(--s6); background: var(--background); color: var(--foreground); border: 0 solid var(--foreground); overflow-y: auto; }
.drawer-content:focus { outline: none; }
.drawer-content[data-side="right"] { top: 0; right: 0; bottom: 0; width: min(420px, 100vw); border-left-width: 1px; animation: drawer-in-right var(--base) var(--ease); } /* physical: explicit right edge, use data-side="end" to follow direction */
.drawer-content[data-side="end"] { top: 0; inset-inline-end: 0; bottom: 0; width: min(420px, 100vw); border-inline-start-width: 1px; animation: drawer-in-end var(--base) var(--ease); }
.drawer-content[data-side="left"] { top: 0; left: 0; bottom: 0; width: min(420px, 100vw); border-right-width: 1px; animation: drawer-in-left var(--base) var(--ease); } /* physical: explicit left edge, use data-side="start" to follow direction */
.drawer-content[data-side="start"] { top: 0; inset-inline-start: 0; bottom: 0; width: min(420px, 100vw); border-inline-end-width: 1px; animation: drawer-in-start var(--base) var(--ease); }
.drawer-content[data-side="top"] { top: 0; inset-inline-start: 0; inset-inline-end: 0; max-height: 80vh; border-bottom-width: 1px; animation: drawer-in-top var(--base) var(--ease); }
.drawer-content[data-side="bottom"] { bottom: 0; inset-inline-start: 0; inset-inline-end: 0; max-height: 80vh; border-top-width: 1px; animation: drawer-in-bottom var(--base) var(--ease); }
@keyframes drawer-in-right { from { transform: translateX(100%); } to { transform: none; } }
@keyframes drawer-in-left { from { transform: translateX(-100%); } to { transform: none; } }
@keyframes drawer-in-end { from { transform: translateX(calc(100% * var(--dir, 1))); } to { transform: none; } }
@keyframes drawer-in-start { from { transform: translateX(calc(-100% * var(--dir, 1))); } to { transform: none; } }
@keyframes drawer-in-top { from { transform: translateY(-100%); } to { transform: none; } }
@keyframes drawer-in-bottom { from { transform: translateY(100%); } to { transform: none; } }

/* Sidebar: a navigation column that collapses to icons from 800px; below that it is hidden and the same content opens in a Drawer. */
.sidebar { --sidebar-collapsed: calc(var(--s7) + var(--s3)); display: none; inline-size: var(--side); flex: none; border-inline-end: 1px solid var(--rule); background: var(--background); transition: inline-size var(--base) var(--ease); }
.sidebar[data-collapsed] { inline-size: var(--sidebar-collapsed); }
.sidebar-inner { position: sticky; inset-block-start: var(--navbar-h, 0rem); display: flex; flex-direction: column; gap: var(--s4); box-sizing: border-box; min-block-size: min(100%, calc(100dvh - var(--navbar-h, 0rem))); max-block-size: calc(100dvh - var(--navbar-h, 0rem)); padding: var(--s4) var(--s3); overflow: hidden auto; }
.sidebar-header { display: flex; align-items: center; justify-content: space-between; gap: var(--s3); min-block-size: var(--control-sm); padding-inline: var(--s2); font-family: var(--font-display); font-weight: 700; font-size: var(--text-lg); }
.sidebar-footer { margin-block-start: auto; display: flex; flex-direction: column; gap: var(--s2); }
.sidebar-content { display: flex; flex-direction: column; gap: var(--s4); }
.sidebar-group { display: flex; flex-direction: column; gap: var(--s1); }
.sidebar-group-label { padding-inline: var(--s3); font-size: var(--text-xs); text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
.sidebar-list { display: flex; flex-direction: column; margin: 0; padding: 0; list-style: none; }
.sidebar-item { display: flex; align-items: center; gap: var(--s3); min-block-size: var(--control-sm); padding: var(--s2) var(--s3); font-size: var(--text-sm); color: var(--muted); text-decoration: none; border-inline-start: 2px solid transparent; }
.sidebar-item:hover { color: var(--foreground); background: var(--wash); }
.sidebar-item[aria-current="page"] { color: var(--foreground); border-inline-start-color: var(--accent); background: var(--wash); }
.sidebar-item:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.sidebar-icon { display: inline-flex; flex: none; inline-size: var(--s4); block-size: var(--s4); }
.sidebar-icon > svg { inline-size: 100%; block-size: 100%; }
.sidebar-label { min-inline-size: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sidebar-toggle { display: none; }
.sidebar-toggle svg { display: block; }
[dir="rtl"] .sidebar-toggle svg { transform: scaleX(-1); }

/* Collapsed: icons only. Labels stay in the accessibility tree and show in a tooltip. */
.sidebar[data-collapsed] .sidebar-label,
.sidebar[data-collapsed] .sidebar-group-label { position: absolute; inline-size: 1px; block-size: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.sidebar[data-collapsed] .sidebar-item { justify-content: center; padding-inline: var(--s2); border-inline-start-color: transparent; }
.sidebar[data-collapsed] .sidebar-item[aria-current="page"] { box-shadow: inset 0 -2px 0 var(--accent); }
.sidebar[data-collapsed] .sidebar-group + .sidebar-group { padding-block-start: var(--s4); border-block-start: 1px solid var(--rule); }
.sidebar[data-collapsed] .sidebar-header { justify-content: center; padding-inline: 0; }
.sidebar[data-collapsed] .sidebar-inner { padding-inline: var(--s2); }

/* The drawer (below 800px) is never collapsed. */
.sidebar-drawer { gap: var(--s4); padding: var(--s4); inline-size: min(var(--side), 100vw); }
.sidebar-drawer .sidebar-toggle, .sidebar-drawer .sidebar-header { display: none; } /* the drawer title takes the header's place */

@media (min-width: 800px) {
  .sidebar { display: block; }
  .sidebar-toggle { display: inline-grid; }
  .sidebar-trigger { display: none; }
}

